begin;
create table internal.intelligence_execution_bindings(school_id uuid not null,id uuid not null default gen_random_uuid(),version integer not null check(version>0),policy_version integer not null check(policy_version>0),manifest jsonb not null,approved_by uuid not null,effective_at timestamptz not null default clock_timestamp(),approval_source text not null check(approval_source in('EXPLICIT_SCHOOL_POLICY','SOURCE_AUTHORIZED_FIXTURE')),primary key(school_id,id),unique(school_id,version),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id),check(jsonb_typeof(manifest)='object'and octet_length(manifest::text)<=8192));
alter table internal.intelligence_execution_bindings enable row level security;alter table internal.intelligence_execution_bindings force row level security;
create trigger execution_binding_immutable before update or delete on internal.intelligence_execution_bindings for each row execute function internal.academic_history_immutable();create trigger execution_binding_no_truncate before truncate on internal.intelligence_execution_bindings for each statement execute function internal.academic_history_immutable();
revoke all on internal.intelligence_execution_bindings from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
alter table app.intelligence_runs add column execution_binding_id uuid;
alter table app.intelligence_runs add column execution_binding_version integer;
alter table app.intelligence_runs add foreign key(school_id,execution_binding_id)references internal.intelligence_execution_bindings(school_id,id);
alter table app.intelligence_runs add check((execution_binding_id is null and execution_binding_version is null)or(execution_binding_id is not null and execution_binding_version is not null and execution_binding_version>0));
create function internal.execution_run_binding_integrity()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.execution_binding_id is not null and not exists(select 1 from internal.intelligence_execution_bindings binding where binding.school_id=new.school_id and binding.id=new.execution_binding_id and binding.version=new.execution_binding_version and binding.policy_version=new.policy_version and binding.manifest->>'mode'=new.generation_mode and binding.manifest->>'provider'=new.provider and binding.manifest->>'model'=new.model and binding.manifest->>'promptId'=new.prompt_id and binding.manifest->>'promptVersion'=new.prompt_version and binding.manifest->>'promptDigest'=new.prompt_digest)then raise exception 'Exact immutable execution binding required'using errcode='22023';end if;return new;
end$$;
create trigger execution_run_binding_integrity before insert or update on app.intelligence_runs for each row execute function internal.execution_run_binding_integrity();
create function internal.valid_intelligence_execution_manifest(manifest jsonb)returns boolean language plpgsql immutable set search_path=''as $$begin
 if manifest is null or jsonb_typeof(manifest)<>'object'or not(manifest?&array['version','purpose','capabilities','mode','provider','model','promptId','promptVersion','promptDigest','promptSource','promptEffectiveAt','evaluationVersion','dataClassification','providerDataPolicy','maxOutputTokens','timeoutMs','maxCost'])or manifest-array['version','purpose','capabilities','mode','provider','model','promptId','promptVersion','promptDigest','promptSource','promptEffectiveAt','evaluationVersion','dataClassification','providerDataPolicy','maxOutputTokens','timeoutMs','maxCost']<>'{}'::jsonb then return false;end if;
 if manifest->>'version'is distinct from'teacher-insight-1'or manifest->>'purpose'is distinct from'NEXT_LEARNING_ACTION'or manifest->'capabilities'is distinct from'["GROUNDED_EXPLANATION","RECOMMENDATION"]'::jsonb or manifest->>'mode'is null or manifest->>'mode'not in('FIXTURE','LIVE')or manifest->>'provider'is null or length(manifest->>'provider')not between 1 and 100 or manifest->>'model'is null or length(manifest->>'model')not between 1 and 100 or manifest->>'promptId'is distinct from'next-learning-action'or manifest->>'promptSource'is distinct from'SOURCE_CONTROLLED_TASK_POLICY'or manifest->>'evaluationVersion'is distinct from'source-78-checked-evidence-1'or manifest->>'dataClassification'is null or manifest->>'dataClassification'not in('SCHOOL_CUSTOM_NUMERIC','SCHOOL_CUSTOM_NATIVE')or manifest->>'providerDataPolicy'is null or manifest->>'providerDataPolicy'not in('LOCAL_SYNTHETIC_FIXTURE','SYNTHETIC_ONLY','APPROVED')then return false;end if;
 if (case manifest->>'promptVersion'when'1'then manifest->>'promptDigest'is distinct from'a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077'when'2'then manifest->>'promptDigest'is distinct from'1f892110e486d0f8117e53ef9d9cf0a884b7c155821dd8eb1284cef22b9f0de4'when'3'then manifest->>'promptDigest'is distinct from'02cb6c151d57fa9e7c17c861ccea6561c1a6c400fcd3814736eb01a22d442e2c'else true end) then return false;end if;
 if manifest->>'promptEffectiveAt'is distinct from (case when manifest->>'promptVersion'='1'then'2026-10-01T00:00:00Z'else'2026-10-02T00:00:00Z'end) or manifest->>'maxOutputTokens'is null or manifest->>'maxOutputTokens'!~'^[0-9]+$'or(manifest->>'maxOutputTokens')::integer not between 1 and 4000 or manifest->>'timeoutMs'is null or manifest->>'timeoutMs'!~'^[0-9]+$'or(manifest->>'timeoutMs')::integer not between 1 and 30000 or jsonb_typeof(manifest->'maxCost')is distinct from'number'or(manifest->>'maxCost')::numeric<=0 or(manifest->>'maxCost')::numeric>10 then return false;end if;
 if manifest->>'mode'='FIXTURE'and(manifest->>'provider'<>'deterministic-fixture'or manifest->>'model'<>'source-locked-v1'or manifest->>'providerDataPolicy'<>'LOCAL_SYNTHETIC_FIXTURE')then return false;end if;
 if manifest->>'mode'='LIVE'and(manifest->>'provider'<>'azure-foundry'or manifest->>'providerDataPolicy'not in('SYNTHETIC_ONLY','APPROVED'))then return false;end if;
 return true;
exception when numeric_value_out_of_range or invalid_text_representation then return false;end$$;
create function internal.approve_intelligence_execution(manifest jsonb,request_id text)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();policy app.intelligence_policies;latest integer;begin
 if not"authorization".improvement_access(school)or"authorization".current_role(school)<>'admin'then raise exception 'Execution binding administrator required'using errcode='42501';end if;
 if not internal.valid_intelligence_execution_manifest(manifest)then raise exception 'Known execution manifest required'using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('school-intelligence-policy:'||school::text,0));
 select*into policy from app.intelligence_policies where school_id=school;
 if policy.school_id is null or policy.data_classification is distinct from manifest->>'dataClassification'or(manifest->>'mode'='FIXTURE'and not policy.fixture_enabled)or(manifest->>'mode'='LIVE'and not policy.live_enabled)then raise exception 'Current approved purpose required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('intelligence-execution-binding:'||school::text,0));
 if exists(select 1 from internal.intelligence_execution_bindings binding where binding.school_id=school and binding.policy_version=policy.version and binding.manifest=approve_intelligence_execution.manifest)then return;end if;
 select coalesce(max(version),0)into latest from internal.intelligence_execution_bindings where school_id=school;
 insert into internal.intelligence_execution_bindings(school_id,version,policy_version,manifest,approved_by,approval_source)values(school,latest+1,policy.version,manifest,"authorization".actor_id(),'EXPLICIT_SCHOOL_POLICY');
 perform internal.append_audit('intelligence.execution.approved','school',school,request_id,'succeeded',jsonb_build_object('version',latest+1,'policyVersion',policy.version));
 perform internal.enqueue_event('intelligence.execution.approved','school',school,latest+1,jsonb_build_object('policyVersion',policy.version),'intelligence-execution-approved:'||school::text||':'||(latest+1)::text);
end$$;
create function internal.read_intelligence_execution_binding()returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();binding internal.intelligence_execution_bindings;begin
 if not"authorization".improvement_access(school)or"authorization".current_role(school)not in('admin','teacher')then raise exception 'Execution registry read denied'using errcode='42501';end if;
 select*into binding from internal.intelligence_execution_bindings where school_id=school order by version desc limit 1;
 return case when binding.id is null then null else jsonb_build_object('id',binding.id,'version',binding.version,'policyVersion',binding.policy_version,'manifest',binding.manifest,'approvedBy',binding.approved_by,'effectiveAt',binding.effective_at,'approvalSource',binding.approval_source)end;
end$$;
create function internal.require_intelligence_execution(manifest jsonb,target_run uuid default null)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();policy app.intelligence_policies;binding internal.intelligence_execution_bindings;run app.intelligence_runs;latest integer;begin
 if not internal.valid_intelligence_execution_manifest(manifest)or not"authorization".improvement_access(school)or"authorization".current_role(school)not in('admin','teacher')then raise exception 'Execution binding source denied'using errcode='42501';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('school-intelligence-policy:'||school::text,0));
 select*into policy from app.intelligence_policies where school_id=school;
 if policy.school_id is null or policy.data_classification is distinct from manifest->>'dataClassification'or(manifest->>'mode'='FIXTURE'and not policy.fixture_enabled)or(manifest->>'mode'='LIVE'and not policy.live_enabled)then raise exception 'Current execution purpose and mode required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('intelligence-execution-binding:'||school::text,0));
 select*into binding from internal.intelligence_execution_bindings where school_id=school and policy_version=policy.version order by version desc limit 1;
 if target_run is not null then
  select*into run from app.intelligence_runs where school_id=school and id=target_run and actor_id="authorization".actor_id();
  if run.id is null or run.state<>'REASONING'or run.generation_mode is distinct from manifest->>'mode'or run.provider is distinct from manifest->>'provider'or run.model is distinct from manifest->>'model'or run.prompt_id is distinct from manifest->>'promptId'or run.prompt_version is distinct from manifest->>'promptVersion'or run.policy_version is distinct from policy.version or run.max_tokens is distinct from(manifest->>'maxOutputTokens')::integer or run.timeout_ms is distinct from(manifest->>'timeoutMs')::integer or run.max_cost is distinct from(manifest->>'maxCost')::numeric then raise exception 'Exact configured execution run required'using errcode='22023';end if;
  if run.execution_binding_id is not null then if run.execution_binding_id is distinct from binding.id or run.execution_binding_version is distinct from binding.version or binding.manifest is distinct from manifest then raise exception 'Execution run binding immutable'using errcode='22023';end if;return;end if;
 end if;
 if binding.id is null and manifest->>'mode'='FIXTURE'and policy.fixture_enabled and policy.data_classification=manifest->>'dataClassification'then
  -- Retained source authority permits local synthetic fixture mechanics, never live processing.
  select coalesce(max(version),0)into latest from internal.intelligence_execution_bindings where school_id=school;
  insert into internal.intelligence_execution_bindings(school_id,version,policy_version,manifest,approved_by,effective_at,approval_source)values(school,latest+1,policy.version,manifest,policy.approved_by,greatest(policy.approved_at,(manifest->>'promptEffectiveAt')::timestamptz),'SOURCE_AUTHORIZED_FIXTURE')returning*into binding;
  perform internal.append_audit('intelligence.execution.fixture_registered','school',school,'source-authorized-fixture-registry','succeeded',jsonb_build_object('bindingId',binding.id,'policyVersion',policy.version));
 end if;
 if binding.id is null or binding.manifest is distinct from manifest then raise exception 'Execution configuration requires school approval'using errcode='22023';end if;
 if binding.effective_at>clock_timestamp()then raise exception 'Execution approval is not yet effective'using errcode='22023';end if;
 if target_run is not null then
  select*into run from app.intelligence_runs where school_id=school and id=target_run and actor_id="authorization".actor_id();
  if run.id is null or run.state<>'REASONING'then raise exception 'New execution run source denied'using errcode='42501';end if;
  update app.intelligence_runs set execution_binding_id=binding.id,execution_binding_version=binding.version where school_id=school and id=run.id;
 perform internal.append_audit('intelligence.execution.bound','intelligence_run',run.id,run.request_id,'succeeded',jsonb_build_object('bindingId',binding.id,'version',binding.version));
 perform internal.enqueue_event('intelligence.execution.bound','intelligence_run',run.id,1,jsonb_build_object('bindingId',binding.id),'intelligence-execution-bound:'||run.id::text);
 end if;
end$$;
-- A source-controlled manifest is provided by the server, never browser analyze fields.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.intelligence_run_immutable()'::regprocedure);anchor:='-''tool_trace''-''selected_activity_id''-''analysis''';if position(anchor in definition)=0 then raise exception 'Run binding immutability source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'-''execution_binding_id''-''execution_binding_version'''||anchor);definition:=replace(definition,'or(old.prompt_digest is not null and new.tool_trace is distinct from old.tool_trace)','or(old.execution_binding_id is not null and(row(new.execution_binding_id,new.execution_binding_version)is distinct from row(old.execution_binding_id,old.execution_binding_version)))or(old.prompt_digest is not null and new.tool_trace is distinct from old.tool_trace)');execute definition;
 definition:=pg_get_functiondef('internal.begin_teacher_insight_run(text,text,uuid,jsonb,text)'::regprocedure);
 anchor:='context:=internal.intelligence_context(baseline_id);';if position(anchor in definition)=0 then raise exception 'Run execution manifest source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,anchor||'if settings->>''mode''=''LIVE''and not(settings?''executionManifest'')then raise exception ''Explicit approved live execution manifest required''using errcode=''22023'';end if;if settings?''executionManifest''then perform internal.require_intelligence_execution(settings->''executionManifest'');end if;');
 definition:=replace(definition,anchor,anchor||'if settings?''executionManifest''and(settings->>''mode''is distinct from settings->''executionManifest''->>''mode''or settings->>''provider''is distinct from settings->''executionManifest''->>''provider''or settings->>''model''is distinct from settings->''executionManifest''->>''model''or settings->>''promptId''is distinct from settings->''executionManifest''->>''promptId''or settings->>''promptVersion''is distinct from settings->''executionManifest''->>''promptVersion''or settings->>''promptDigest''is distinct from settings->''executionManifest''->>''promptDigest''or settings->>''maxTokens''is distinct from settings->''executionManifest''->>''maxOutputTokens''or settings->>''timeoutMs''is distinct from settings->''executionManifest''->>''timeoutMs''or settings->>''maxCost''is distinct from settings->''executionManifest''->>''maxCost'')then raise exception ''Execution manifest settings mismatch''using errcode=''22023'';end if;');
 definition:=replace(definition,'-''globalDailyBudget''','-''globalDailyBudget''-''executionManifest''');
 anchor:='if reservation->>''state''=''NEW''and settings?''promptDigest''then return jsonb_set';if position(anchor in definition)=0 then raise exception 'Final execution binding timing changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'if reservation->>''state''=''NEW''and settings?''promptDigest''then if settings?''executionManifest''then perform internal.require_intelligence_execution(settings->''executionManifest'',(reservation->>''runId'')::uuid);end if; return jsonb_set');execute definition;
end$$;
-- Execution metadata acknowledgment does not create educational inference.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Execution event dispatcher changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''intelligence.execution.bound'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.version<>1 or e.entity_type<>''intelligence_run''or not exists(select 1 from app.intelligence_runs run where run.school_id=e.school_id and run.id=e.entity_id and run.actor_id=e.actor_id and run.execution_binding_id::text=e.metadata->>''bindingId'')then raise exception ''Execution binding event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Execution binding event lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''intelligence.execution.approved'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''school''or e.entity_id<>e.school_id or not exists(select 1 from internal.intelligence_execution_bindings binding where binding.school_id=e.school_id and binding.version=e.version and binding.approved_by=e.actor_id and binding.policy_version::text=e.metadata->>''policyVersion'')then raise exception ''Execution approval event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Execution approval event lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
end$$;
revoke execute on function internal.valid_intelligence_execution_manifest(jsonb),internal.approve_intelligence_execution(jsonb,text),internal.read_intelligence_execution_binding(),internal.require_intelligence_execution(jsonb,uuid),internal.execution_run_binding_integrity()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.approve_intelligence_execution(jsonb,text),internal.read_intelligence_execution_binding()to cuevo_api;
commit;
